style.css:
@-moz-document domain("xtramath.org") {
/* Background */
body {
    background: #97abab !important;
    font-family: Georgia, serif !important;
}

/* Top bar */
header,
nav,
.navbar,
.topbar {
    background: linear-gradient(#8fa3a3, #869999) !important;
    box-shadow: 0 2px 8px rgba(0,0,0,.25) !important;
}

/* Main content box */
main,
.container,
.content,
div[class*="card"],
div[class*="lesson"] {
    background: #f7f7f7 !important;
    border-radius: 12px !important;
    box-shadow: 0 3px 10px rgba(0,0,0,.25) !important;
    border: none !important;
}

/* Titles */
h1, h2 {
    color: #444 !important;
    font-family: Georgia, serif !important;
    font-weight: normal !important;
}

/* Green classic buttons */
button,
input[type="submit"],
.btn {
    background: linear-gradient(#9fd84c, #78b92f) !important;
    border: 1px solid #6a9828 !important;
    border-radius: 10px !important;
    color: white !important;
    padding: 8px 22px !important;
    font-size: 16px !important;
    box-shadow:
        inset 0 1px 0 rgba(255,255,255,.5),
        0 1px 3px rgba(0,0,0,.3) !important;
}

/* Hover */
button:hover,
input[type="submit"]:hover,
.btn:hover {
    filter: brightness(1.08);
}
}
